import { DatabaseSync, constants } from 'node:sqlite';
function main(): void {
  const db = new DatabaseSync(':memory:');
  db.exec('CREATE TABLE p (id INTEGER, label TEXT, weight REAL, body BLOB)');
  const stmt = db.prepare('SELECT id, label AS shown, weight, body FROM p WHERE id = ?');
  console.log(stmt.sourceSQL);
  console.log(stmt.expandedSQL);
  stmt.get(7);
  console.log(stmt.expandedSQL);
  console.log(JSON.stringify(stmt.columns()));
  console.log(constants.SQLITE_CHANGESET_CONFLICT, constants.SQLITE_CHANGESET_FOREIGN_KEY, Object.keys(constants).length);
  db.close();
}
